children:
:root {
  --blog-ink: #06111d;
  --blog-soft: rgba(6, 17, 29, 0.68);
  --blog-paper: #f7f8fb;
  --blog-line: rgba(6, 17, 29, 0.13);
  --blog-red: #f31248;
  --blog-night: #05080d;
  --blog-panel: #ffffff;
  --blog-muted-panel: #eef2f5;
}

html {
  scroll-behavior: smooth;
}

body.body.crays-mirror.route-blog {
  margin: 0;
  background: var(--blog-paper);
  color: var(--blog-ink);
  font-family: Montserrat, Arial, sans-serif;
  letter-spacing: 0;
}

.crays-blog-page {
  overflow: hidden;
  background: var(--blog-paper);
}

.crays-blog-shell {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
}

.crays-blog-eyebrow {
  margin: 0 0 14px;
  color: var(--blog-red);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.crays-blog-hero {
  position: relative;
  min-height: 760px;
  padding: 134px 0 64px;
  color: #fff;
  background: var(--blog-night);
}

.crays-blog-hero__media {
  position: absolute;
  inset: 0;
  margin: 0;
}

.crays-blog-hero__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.72;
  filter: saturate(0.94) contrast(1.03);
}

.crays-blog-hero__shade {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(3, 7, 12, 0.94) 0%, rgba(3, 7, 12, 0.78) 46%, rgba(3, 7, 12, 0.3) 100%),
    linear-gradient(0deg, rgba(3, 7, 12, 0.98) 0%, rgba(3, 7, 12, 0) 42%);
}

.crays-blog-hero__inner {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(320px, 0.48fr);
  gap: clamp(36px, 6vw, 86px);
  align-items: end;
  min-height: 560px;
}

.crays-blog-hero h1 {
  max-width: 900px;
  margin: 0;
  color: #fff;
  font-family: Montserrat, Arial, sans-serif;
  font-size: clamp(52px, 7vw, 104px);
  font-weight: 900;
  line-height: 0.96;
  letter-spacing: 0;
}

.crays-blog-hero__lead {
  max-width: 690px;
  margin: 28px 0 0;
  color: rgba(255, 255, 255, 0.76);
  font-size: clamp(17px, 1.25vw, 20px);
  line-height: 1.65;
  font-weight: 500;
}

.crays-blog-hero__panel {
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 8px;
  background: rgba(5, 8, 13, 0.74);
  padding: clamp(24px, 3vw, 34px);
  backdrop-filter: blur(16px);
}

.crays-blog-hero__panel strong {
  display: block;
  color: #fff;
  font-size: clamp(22px, 2vw, 30px);
  line-height: 1.12;
  font-weight: 900;
}

.crays-blog-hero__panel p {
  margin: 18px 0 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: 15px;
  line-height: 1.7;
}

.crays-blog-nav {
  position: sticky;
  top: 72px;
  z-index: 4;
  border-bottom: 1px solid var(--blog-line);
  background: rgba(247, 248, 251, 0.94);
  backdrop-filter: blur(18px);
}

.crays-blog-nav__inner {
  display: flex;
  gap: 10px;
  align-items: center;
  overflow-x: auto;
  padding: 14px 0;
  scrollbar-width: none;
}

.crays-blog-nav__inner::-webkit-scrollbar {
  display: none;
}

.crays-blog-nav a {
  flex: 0 0 auto;
  border: 1px solid var(--blog-line);
  border-radius: 999px;
  padding: 10px 15px;
  color: var(--blog-ink);
  font-size: 13px;
  font-weight: 800;
  line-height: 1;
  text-decoration: none;
  background: rgba(255, 255, 255, 0.7);
}

.crays-blog-nav a:hover {
  border-color: rgba(243, 18, 72, 0.46);
  color: var(--blog-red);
}

.crays-blog-section {
  padding: clamp(70px, 8vw, 116px) 0;
}

.crays-blog-section--dark {
  background: var(--blog-night);
  color: #fff;
}

.crays-blog-section-head {
  display: grid;
  grid-template-columns: minmax(0, 0.78fr) minmax(300px, 0.38fr);
  gap: 38px;
  align-items: end;
  margin-bottom: 34px;
}

.crays-blog-section-head h2 {
  margin: 0;
  color: inherit;
  font-size: clamp(34px, 4vw, 64px);
  font-weight: 900;
  line-height: 1.02;
  letter-spacing: 0;
}

.crays-blog-section-head p {
  margin: 0;
  color: var(--blog-soft);
  font-size: 16px;
  line-height: 1.72;
  font-weight: 500;
}

.crays-blog-section--dark .crays-blog-section-head p,
.crays-blog-section--dark .crays-blog-story p,
.crays-blog-section--dark .crays-blog-channel p {
  color: rgba(255, 255, 255, 0.68);
}

.crays-blog-feature-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(320px, 0.42fr);
  gap: 22px;
}

.crays-blog-feature-main,
.crays-blog-feature-side,
.crays-blog-channel,
.crays-blog-story,
.crays-blog-archive-card,
.crays-blog-editor-note {
  border: 1px solid var(--blog-line);
  border-radius: 8px;
  background: var(--blog-panel);
  overflow: hidden;
}

.crays-blog-feature-main {
  display: grid;
  grid-template-columns: minmax(0, 0.74fr) minmax(300px, 0.48fr);
  min-height: 430px;
}

.crays-blog-feature-main figure,
.crays-blog-feature-side figure,
.crays-blog-story figure {
  margin: 0;
  overflow: hidden;
  background: #d9e0e6;
}

.crays-blog-feature-main img,
.crays-blog-feature-side img,
.crays-blog-story img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.crays-blog-feature-main img[src^="/assets/blog/"],
.crays-blog-feature-side img[src^="/assets/blog/"],
.crays-blog-story img[src^="/assets/blog/"] {
  object-fit: contain;
  background: #05080d;
}

.crays-blog-feature-main__body {
  display: flex;
  flex-direction: column;
  padding: clamp(26px, 3.4vw, 42px);
}

.crays-blog-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-bottom: 17px;
  color: var(--blog-red);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.crays-blog-feature-main h3,
.crays-blog-feature-side h3,
.crays-blog-story h3,
.crays-blog-channel h3,
.crays-blog-archive-card h3 {
  margin: 0;
  color: var(--blog-ink);
  font-size: clamp(24px, 2.2vw, 36px);
  font-weight: 900;
  line-height: 1.08;
  letter-spacing: 0;
}

.crays-blog-feature-main h3 a,
.crays-blog-feature-side h3 a,
.crays-blog-story h3 a {
  color: inherit;
  text-decoration: none;
}

.crays-blog-feature-main h3 a:hover,
.crays-blog-feature-side h3 a:hover,
.crays-blog-story h3 a:hover {
  color: var(--blog-red);
}

.crays-blog-feature-main p,
.crays-blog-feature-side p,
.crays-blog-story p,
.crays-blog-channel p,
.crays-blog-archive-card p {
  margin: 18px 0 0;
  color: var(--blog-soft);
  font-size: 15px;
  line-height: 1.68;
  font-weight: 500;
}

.crays-blog-read-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: auto;
  padding-top: 24px;
  color: var(--blog-ink);
  font-size: 13px;
  font-weight: 900;
  text-decoration: none;
}

.crays-blog-read-link:hover {
  color: var(--blog-red);
}

.crays-blog-feature-stack {
  display: grid;
  gap: 22px;
}

.crays-blog-feature-side {
  display: grid;
  grid-template-columns: 138px minmax(0, 1fr);
  min-height: 204px;
}

.crays-blog-feature-side__body {
  padding: 22px;
}

.crays-blog-feature-side h3 {
  font-size: 22px;
  line-height: 1.12;
}

.crays-blog-channel-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 16px;
}

.crays-blog-channel {
  padding: 24px;
  min-height: 210px;
}

.crays-blog-channel span {
  display: inline-flex;
  color: var(--blog-red);
  font-size: 12px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.crays-blog-channel h3 {
  margin-top: 46px;
  font-size: 24px;
}

.crays-blog-channel a {
  color: inherit;
  text-decoration: none;
}

.crays-blog-story-list {
  display: grid;
  gap: 14px;
}

.crays-blog-story {
  display: grid;
  grid-template-columns: 172px minmax(0, 0.34fr) minmax(0, 1fr) auto;
  gap: 24px;
  align-items: center;
  padding: 14px;
}

.crays-blog-story figure {
  height: 118px;
  border-radius: 6px;
}

.crays-blog-story__number {
  color: rgba(6, 17, 29, 0.24);
  font-size: 42px;
  font-weight: 900;
  line-height: 1;
}

.crays-blog-story h3 {
  font-size: clamp(20px, 1.65vw, 28px);
}

.crays-blog-story p {
  margin-top: 10px;
  max-width: 64ch;
}

.crays-blog-story__date {
  justify-self: end;
  color: var(--blog-soft);
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  white-space: nowrap;
}

.crays-blog-archive-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
}

.crays-blog-archive-card {
  padding: 24px;
  background: rgba(255, 255, 255, 0.06);
  border-color: rgba(255, 255, 255, 0.14);
}

.crays-blog-archive-card h3 {
  color: #fff;
  font-size: 22px;
}

.crays-blog-archive-card ul {
  display: grid;
  gap: 12px;
  margin: 22px 0 0;
  padding: 0;
  list-style: none;
}

.crays-blog-archive-card a {
  color: rgba(255, 255, 255, 0.72);
  font-size: 14px;
  font-weight: 700;
  text-decoration: none;
}

.crays-blog-archive-card a:hover {
  color: #fff;
}

.crays-blog-editor-note {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 0.36fr);
  gap: 34px;
  align-items: center;
  padding: clamp(28px, 4vw, 52px);
  background: var(--blog-ink);
  color: #fff;
}

.crays-blog-editor-note h2 {
  margin: 0;
  color: #fff;
  font-size: clamp(30px, 3.4vw, 54px);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: 0;
}

.crays-blog-editor-note p {
  margin: 18px 0 0;
  color: rgba(255, 255, 255, 0.72);
  font-size: 16px;
  line-height: 1.7;
}

.crays-blog-editor-note a {
  justify-self: end;
  border: 1px solid rgba(255, 255, 255, 0.24);
  border-radius: 999px;
  padding: 14px 22px;
  color: #fff;
  font-size: 13px;
  font-weight: 900;
  text-decoration: none;
}

.crays-blog-editor-note a:hover {
  border-color: var(--blog-red);
  color: var(--blog-red);
}

@media (max-width: 1120px) {
  .crays-blog-hero__inner,
  .crays-blog-section-head,
  .crays-blog-feature-grid,
  .crays-blog-feature-main,
  .crays-blog-editor-note {
    grid-template-columns: minmax(0, 1fr);
  }

  .crays-blog-channel-grid,
  .crays-blog-archive-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .crays-blog-feature-main figure {
    aspect-ratio: 16 / 10;
  }

  .crays-blog-editor-note a {
    justify-self: start;
  }
}

@media (max-width: 820px) {
  .crays-blog-shell {
    width: min(100% - 32px, 1180px);
  }

  .crays-blog-hero {
    min-height: 700px;
    padding-top: 118px;
  }

  .crays-blog-hero h1 {
    font-size: clamp(42px, 13vw, 64px);
  }

  .crays-blog-nav {
    top: 64px;
  }

  .crays-blog-feature-side,
  .crays-blog-story {
    grid-template-columns: minmax(0, 1fr);
  }

  .crays-blog-feature-side figure,
  .crays-blog-story figure {
    height: auto;
    aspect-ratio: 16 / 9;
  }

  .crays-blog-story__number,
  .crays-blog-story__date {
    justify-self: start;
  }

  .crays-blog-channel-grid,
  .crays-blog-archive-grid {
    grid-template-columns: minmax(0, 1fr);
  }
}

(function () {
      var panel = document.querySelector('[data-crays-consent-panel]');
      if (!panel) return;
      var storageKey = 'crays-cookie-consent';
      function openPanel() {
        panel.hidden = false;
        panel.classList.add('is-open');
      }
      function closePanel(value) {
        if (value) {
          try { window.localStorage.setItem(storageKey, value); } catch (error) {}
        }
        panel.classList.remove('is-open');
        panel.hidden = true;
      }
      document.querySelectorAll('[data-crays-consent-open]').forEach(function (button) {
        button.addEventListener('click', openPanel);
      });
      panel.querySelectorAll('[data-crays-consent-close]').forEach(function (button) {
        button.addEventListener('click', function () { closePanel(button.getAttribute('data-crays-consent-close')); });
      });
    })();
